INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Kundenwünsche immer technisch umsetzbar?', 2, '[{"text": "Nein", "correct": true, "because": "Machbarkeit kann begrenzen"}, {"text": "Ja", "correct": false, "because": "Nicht immer realistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Anforderungsabgleich?', 3, '[{"text": "Klarheit über Umsetzbarkeit schaffen", "correct": true, "because": "Abstimmung von Wunsch und Realität"}, {"text": "Code sofort schreiben", "correct": false, "because": "Zu früh"}, {"text": "UI gestalten", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren prüfe ich bei der Machbarkeit?', 5, '[{"text": "Technische Ressourcen", "correct": true, "because": "Bestimmen Möglichkeiten"}, {"text": "Zeitrahmen", "correct": true, "because": "Beeinflusst Planung"}, {"text": "Farbauswahl", "correct": false, "because": "Irrelevant"}, {"text": "Marketingstrategie", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anforderungen müssen dokumentiert werden. b) Sie sind immer klar formuliert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft ungenau"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht garantiert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Abgleich mit dem Kunden?', 4, '[{"text": "Technische Limits", "correct": false, "because": "Entscheidend für Machbarkeit"}, {"text": "Kundenprioritäten", "correct": false, "because": "Leiten Anpassung"}, {"text": "Serverdesign", "correct": true, "because": "Späterer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jeder Wunsch machbar ist?', 2, '[{"text": "Nein", "correct": true, "because": "Ressourcen begrenzen"}, {"text": "Ja", "correct": false, "because": "Nicht immer möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Anforderungen zu klären?', 3, '[{"text": "Workshop mit Kunden", "correct": true, "because": "Direkte Abstimmung"}, {"text": "Code direkt anpassen", "correct": false, "because": "Zu früh"}, {"text": "Datenbank erstellen", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind beim Abgleich entscheidend?', 5, '[{"text": "Kundenziele verstehen", "correct": true, "because": "Leitet Anpassung"}, {"text": "Technische Grenzen prüfen", "correct": true, "because": "Sichert Umsetzung"}, {"text": "UI-Layout festlegen", "correct": false, "because": "Später relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Abgleich spart Zeit. b) Er ist nur Formsache. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) unterschätzt Wert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Anforderungsabgleich?', 4, '[{"text": "Kundeninput", "correct": false, "because": "Grundlage der Klärung"}, {"text": "Technisches Wissen", "correct": false, "because": "Bewertet Machbarkeit"}, {"text": "Grafiksoftware", "correct": true, "because": "Nicht primär nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Abgleich optional?', 2, '[{"text": "Nein", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Ja", "correct": false, "because": "Risiko bei Auslassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte mache ich beim Abgleich?', 4, '[{"text": "Anforderungen sammeln", "correct": true, "because": "Basis schaffen"}, {"text": "Machbarkeit prüfen", "correct": true, "because": "Realität abgleichen"}, {"text": "Code kompilieren", "correct": false, "because": "Zu früh"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Abgleich nur für große Projekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine profitieren"}, {"text": "Ja", "correct": false, "because": "Universell nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Abgleich?', 3, '[{"text": "Kundenbedürfnisse klären", "correct": true, "because": "Legt Fokus fest"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Designanpassung", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Machbarkeit hängt von Technik ab. b) Kundenwünsche sind fix.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann verhandelt werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist flexibel"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein guter Abgleich?', 5, '[{"text": "Missverständnisse vermeiden", "correct": true, "because": "Klarheit schaffen"}, {"text": "Zeit sparen", "correct": true, "because": "Effiziente Planung"}, {"text": "Code optimieren", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Abgleich unwichtig?', 3, '[{"text": "Kundendialog", "correct": false, "because": "Kern der Klärung"}, {"text": "Ressourcenanalyse", "correct": false, "because": "Bewertet Machbarkeit"}, {"text": "Farbschema", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich den Abgleich überspringen?', 3, '[{"text": "Nein", "correct": true, "because": "Risiko für Fehlplanung"}, {"text": "Ja", "correct": false, "because": "Abstimmung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Abgleich nur einmal nötig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann iterativ sein"}, {"text": "Ja", "correct": false, "because": "Änderungen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um Wünsche zu priorisieren?', 4, '[{"text": "MoSCoW-Methode", "correct": true, "because": "Klarheit über Must-haves"}, {"text": "Datenbankdesign", "correct": false, "because": "Späterer Schritt"}, {"text": "UI-Mockup", "correct": false, "because": "Visualisierung"}]');
